reg dff2_out;
reg dff3_out;

// Instantiate D Flip-Flops
always @(posedge clk) begin
    dff1_out <= x; // DFF1 driven by X
end

always @(posedge clk) begin
    dff2_out <= ~x; // DFF2 driven by ~X
end

always @(posedge clk) begin
    dff3_out <= x; // DFF3 driven by X (again)
end

