        // Shift the register right
        lfsr <= {lfsr[30:0], lfsr[31]};

        // XOR the tap bits with the new MSB
        lfsr[31] <= lfsr[31] ^ lfsr[30] ^ lfsr[22] ^ lfsr[1];

        // Assign the output
        q <= lfsr;
