    if (areset) begin
        state <= A;
        z <= 1'b0;
    end else begin
        case (state)
            A: begin
                if (x == 1'b0) begin
                    state <= A;
                    z <= 1'b0;
                end else begin
                    state <= B;
                    z <= 1'b1;
                end
            end
            B: begin
                if (x == 1'b0) begin
                    state <= B;
                    z <= 1'b1;
                end else begin
                    state <= B;
                    z <= 1'b0;
                end
            end
            default: state <= A; // Reset to state A in case of unknown state
        endcase
    end
end

