module TopModule (
    input wire clk,
    input wire reset,
    input wire data,
    output reg start_shifting
);

    // State definitions
    typedef enum reg [1:0] {IDLE, FIRST_ONE, SECOND_ONE, THIRD_ZERO} state_t;
    state_t current_state, next_state;

    // Internal signals
    reg found_sequence;

    always @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= IDLE;
        else
            current_state <= next_state;
    end

    always @(*) begin
        case (current_state)
            IDLE:
                if (data == 1'b1)
                    next_state = FIRST_ONE;
                else
                    next_state = IDLE;

            FIRST_ONE:
                if (data == 1'b1)
                    next_state = FIRST_ONE;
                else if (data == 1'b0)
                    next_state = SECOND_ONE;
                else
                    next_state = IDLE;

            SECOND_ONE:
                if (data == 1'b0)
                    next_state = SECOND_ONE;
                else if (data == 1'b1)
                    next_state = THIRD_ZERO;
                else
                    next_state = IDLE;

            THIRD_ZERO:
                if (data == 1'b1)
                    next_state = IDLE;
                else
                    next_state = THIRD_ZERO;

            default:
                next_state = IDLE;
        endcase

        // Sequence detection logic
        found_sequence = (current_state == THIRD_ZERO && data == 1'b1);
    end

    assign start_shifting = found_sequence | reset;

endmodule

module TopModule (
  input clk,
  input reset,
  input data,
  output start_shifting
);

  parameter S=0, S1=1, S11=2, S110=3, Done=4;

  reg [2:0] state, next;

  always_comb begin
    case (state)
      S: next = data ? S1: S;
      S1: next = data ? S11: S;
      S11: next = data ? S11 : S110;
      S110: next = data ? Done : S;
      Done: next = Done;
    endcase
  end

  always @(posedge clk)
    if (reset) state <= S;
    else state <= next;

  assign start_shifting = state == Done;

endmodule

