    case (currentState)
        STATE_A: 
            if (in == 0) nextState = STATE_A;
            else          nextState = STATE_B;
        STATE_B:
            if (in == 0) nextState = STATE_B;
            else          nextState = STATE_B;
        STATE_C:
            if (in == 0) nextState = STATE_A;
            else          nextState = STATE_D;
        STATE_D:
            if (in == 0) nextState = STATE_C;
            else          nextState = STATE_B;
        default: nextState = STATE_A; // Default to state A
    endcase
end

// Output logic
always @(*) begin
    case (currentState)
        STATE_A: out = 0;
        STATE_B: out = 0;
        STATE_C: out = 0;
        STATE_D: out = 1;
        default: out = 0; // Default output
    endcase
