always @(posedge clk or posedge reset) begin
    if (reset) begin
        currentState <= STATE_A; // Reset to state A
        out <= 0;                // Reset output to 0
    end else begin
        case (currentState)
            STATE_A: 
                if (in == 0) begin
                    currentState <= STATE_A;
