            STATE_B: begin
                if (x && y) begin
                    next_state = STATE_C;
                end else if (!x) begin
                    next_state = STATE_A;
                end
            end
            STATE_C: begin
                if (!y) begin
                    next_state = STATE_D;
                end
            end
            STATE_D: begin
                if (x) begin
