    integer consecutive_ones;

    always @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= IDLE;
        else
            current_state <= next_state;
    end

    always @(*) begin
        current_state = IDLE; // Default case for current_state
        next_state = IDLE;   // Default case for next_state
        disc = 1'b0;
        flag = 1'b0;
        err = 1'b0;
        consecutive_ones = 0;

        case (current_state)
            IDLE: begin
                if (in == 1'b0)
                    next_state = IDLE;
                else if (in == 1'b1) begin
                    consecutive_ones = 1;
                    next_state = START_1;
                end
