                    else if (consecutive_ones >= 7)
                        next_state = ERROR;
                    else
                        next_state = START_2;
                end
            end
            START_2: begin
                if (in == 1'b0)
                    next_state = IDLE;
                else if (in == 1'b1) begin
                    consecutive_ones++;
                    if (consecutive_ones == 6)
                        next_state = FLAG_6;
                    else if (consecutive_ones >= 7)
                        next_state = ERROR;
                    else
                        next_state = START_3;
                end
            end
            START_3: begin
                if (in == 1'b0)
                    next_state = IDLE;
                else if (in == 1'b1) begin
                    consecutive_ones++;
                    if (consecutive_ones == 6)
                        next_state = FLAG_6;
                    else if (consecutive_ones >= 7)
                        next_state = ERROR;
                    else
                        next_state = START_4;
                end
            end
            START_4: begin
                if (in == 1'b0)
                    next_state = IDLE;
                else if (in == 1'b1) begin
                    consecutive_ones++;
                    if (consecutive_ones == 6)
                        next_state = FLAG_6;
                    else if (consecutive_ones >= 7)
                        next_state = ERROR;
                    else
                        next_state = START_5;
                end
            end
            START_5: begin
                if (in == 1'b0)
                    next_state = IDLE;
                else if (in == 1'b1) begin
                    consecutive_ones++;
                    if (consecutive_ones == 6)
                        next_state = FLAG_6;
                    else if (consecutive_ones >= 7)
                        next_state = ERROR;
                    else
                        next_state = START_1;
                end
            end
            FLAG_6: begin
                disc = 1'b1;
                if (in == 1'b0)
                    next_state = IDLE;
                else if (in == 1'b1) begin
                    consecutive_ones = 1;
                    next_state = START_1;
                end
            end
            ERROR: begin
                err = 1'b1;
                if (in == 1'b0)
                    next_state = IDLE;
                else if (in == 1'b1) begin
