    end

    always @(*) begin
        next_state = current_state; // Default stay in current state
        walk_left = 1'b0;
        walk_right = 1'b0;
        aaah = 1'b0;
        prev_walk_direction = walk_left ? 2'b10 : 2'b11; // Save previous walk direction

        case (current_state)
            IDLE:
                if (ground == 0) begin
                    next_state = FALLING;
                    aaah = 1'b1;
                end else if (bump_left) begin
                    next_state = WALK_RIGHT;
                    walk_right = 1'b1;
                end else if (bump_right) begin
                    next_state = WALK_LEFT;
                    walk_left = 1'b1;
                end

            FALLING:
                if (ground == 1) begin
                    next_state = (prev_walk_direction == 2'b10) ? WALK_LEFT : WALK_RIGHT;
                    walk_left = (prev_walk_direction == 2'b10);
                    walk_right = (prev_walk_direction == 2'b11);
                end else if (bump_left || bump_right) begin
                    next_state = (prev_walk_direction == 2'b10) ? WALK_RIGHT : WALK_LEFT;
                    walk_right = (prev_walk_direction == 2'b10);
                    walk_left = (prev_walk_direction == 2'b11);
                end

            WALK_LEFT:
                if (ground == 0) begin
                    next_state = FALLING;
                    aaah = 1'b1;
                end else if (bump_right) begin
                    next_state = WALK_RIGHT;
                    walk_right = 1'b1;
                end

            WALK_RIGHT:
                if (ground == 0) begin
                    next_state = FALLING;
                    aaah = 1'b1;
                end else if (bump_left) begin
                    next_state = WALK_LEFT;
                    walk_left = 1'b1;
                end

            default: // Should never reach here
                next_state = IDLE;
        endcase
    end

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  parameter WL=0, WR=1, FALLL=2, FALLR=3;
  reg [1:0] state;
  reg [1:0] next;

  always_comb begin
    case (state)
      WL: next = ground ? (bump_left ? WR : WL) : FALLL;
      WR: next = ground ? (bump_right ? WL: WR) : FALLR;
      FALLL: next = ground ? WL : FALLL;
      FALLR: next = ground ? WR : FALLR;
    endcase
  end

  always @(posedge clk, posedge areset) begin
    if (areset) state <= WL;
      else state <= next;
  end

  assign walk_left = (state==WL);
  assign walk_right = (state==WR);
  assign aaah = (state == FALLL) || (state == FALLR);

endmodule

module TopModule (
  input in,
  input [9:0] state,
  output [9:0] next_state,
  output out1,
  output out2
);

  assign out1 = state[8] | state[9];
  assign out2 = state[7] | state[9];

  assign next_state[0] = !in && (|state[4:0] | state[7] | state[8] | state[9]);
  assign next_state[1] = in && (state[0] | state[8] | state[9]);
  assign next_state[2] = in && state[1];
  assign next_state[3] = in && state[2];
  assign next_state[4] = in && state[3];
  assign next_state[5] = in && state[4];
  assign next_state[6] = in && state[5];
  assign next_state[7] = in && (state[6] | state[7]);
  assign next_state[8] = !in && state[5];
  assign next_state[9] = !in && state[6];

endmodule

module TopModule (
    input wire in,
    input wire [9:0] state,
    output reg [9:0] next_state,
    output reg out1,
    output reg out2
);

always @(*) begin
    // Initialize next_state and outputs
    next_state = 10'b0;
    out1 = 0;
    out2 = 0;

    case (state)
        // State S0 transitions
        10'b0000000001: begin
            if (in == 1'b0) next_state[0] = 1'b1; else next_state[1] = 1'b1;
        end
        // State S1 transitions
        10'b0000000010: begin
            if (in == 1'b0) next_state[0] = 1'b1; else next_state[2] = 1'b1;
        end
        // State S2 transitions
        10'b0000000100: begin
            if (in == 1'b0) next_state[0] = 1'b1; else next_state[3] = 1'b1;
        end
        // State S3 transitions
        10'b0000001000: begin
            if (in == 1'b0) next_state[0] = 1'b1; else next_state[4] = 1'b1;
        end
        // State S4 transitions
        10'b0000010000: begin
            if (in == 1'b0) next_state[0] = 1'b1; else next_state[5] = 1'b1;
        end
        // State S5 transitions
        10'b0000100000: begin
            if (in == 1'b0) next_state[8] = 1'b1; else next_state[6] = 1'b1;
        end
        // State S6 transitions
        10'b0001000000: begin
            if (in == 1'b0) next_state[9] = 1'b1; else next_state[7] = 1'b1;
        end
        // State S7 transitions
        10'b0010000000: begin
            if (in == 1'b1) next_state[0] = 1'b1;
        end
        // State S8 transitions
        10'b0100000000: begin
            if (in == 1'b0) next_state[0] = 1'b1; else next_state[1] = 1'b1;
        end
        // State S9 transitions
        10'b1000000000: begin
            if (in == 1'b0) next_state[0] = 1'b1; else next_state[1] = 1'b1;
        end
        default: ; // Stay in current state
    endcase

    // Output logic based on the current state
    case (state)
        10'b0010000000: out1 = 1'b1; // S7 has out1 set
        10'b0100000000: out2 = 1'b1; // S8 has out2 set
        10'b1000000000: out1 = 1'b1; // S9 has out1 set
        default: ; // No outputs set for other states
    endcase
end

endmodule

module TopModule (
    input wire clock,
    input wire a,
    output reg p,
    output reg q
);

reg [1:0] state;

always @(posedge clock) begin
    case (state)
        2'b00:
            if (!a) begin
                p <= 1'b0;
                q <= 1'b0;
                state <= 2'b00;
            end else begin
                p <= 1'b0;
                q <= 1'b0;
                state <= 2'b01;
            end
        2'b01:
            if (!a) begin
                p <= 1'b0;
                q <= 1'b0;
                state <= 2'b00;
            end else begin
                p <= 1'b1;
                q <= 1'b0;
                state <= 2'b10;
            end
        2'b10:
            if (!a) begin
                p <= 1'b0;
                q <= 1'b0;
                state <= 2'b00;
            end else begin
                p <= 1'b1;
                q <= 1'b1;
                state <= 2'b11;
            end
        2'b11:
            if (!a) begin
                p <= 1'b0;
                q <= 1'b0;
                state <= 2'b00;
            end else begin
                p <= 1'b1;
                q <= 1'b0;
                state <= 2'b01;
            end
    endcase
end

endmodule

module TopModule (
  input clock,
