module TopModule (
    input wire clk,
    input wire in,
    input wire reset,
    output reg [7:0] out_byte,
    output reg done
);

    parameter IDLE = 3'b000,
               START_BIT = 3'b001,
               DATA_BITS = 3'b010,
               STOP_BIT = 3'b011;

    reg [2:0] state;
    reg [2:0] bit_count;
    reg [7:0] shift_reg;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            bit_count <= 3'b000;
            shift_reg <= 8'b00000000;
            out_byte <= 8'b00000000;
            done <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (!in) begin // Detect start bit
                        state <= START_BIT;
                    end
                end
                START_BIT: begin
                    state <= DATA_BITS;
                    bit_count <= 3'b000;
                    shift_reg <= 8'b00000000;
                end
                DATA_BITS: begin
                    shift_reg <= {shift_reg[6:0], in};
                    if (bit_count == 3'b111) begin
                        state <= STOP_BIT;
                    end else begin
                        bit_count <= bit_count + 3'b001;
                    end
                end
                STOP_BIT: begin
                    if (in) begin
                        out_byte <= shift_reg;
                        done <= 1'b1;
                        state <= IDLE; // Wait for start bit to detect next byte
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

endmodule

module TopModule (
  input clk,
  input in,
  input reset,
  output [7:0] out_byte,
  output done
);

  parameter B0=0, B1=1, B2=2, B3=3, B4=4, B5=5, B6=6, B7=7, START=8, STOP=9, DONE=10, ERR=11;
  reg [3:0] state;
  reg [3:0] next;

  reg [9:0] byte_r;

  always_comb begin
    case (state)
      START: next = in ? START : B0;  // start bit is 0
      B0: next = B1;
      B1: next = B2;
      B2: next = B3;
      B3: next = B4;
      B4: next = B5;
      B5: next = B6;
      B6: next = B7;
      B7: next = STOP;
      STOP: next = in ? DONE : ERR;  // stop bit is 1. Idle state is 1.
      DONE: next = in ? START : B0;
      ERR: next = in ? START : ERR;
    endcase
  end

  always @(posedge clk) begin
    if (reset) state <= START;
      else state <= next;
  end

  always @(posedge clk) begin
    byte_r <= {in, byte_r[9:1]};
  end

  assign done = (state==DONE);
  assign out_byte = done ? byte_r[8:1] : 8'hx;

endmodule

module TopModule (
  input clk,
  input a,
  input b,
  output q,
  output state
);

  reg c;
  always @(posedge clk)
    c <= a&b | a&c | b&c;

  assign q = a^b^c;
  assign state = c;

endmodule

module TopModule (
    input clk,
    input a,
    input b,
    output reg q,
    output reg state
);
    reg dff;

    always @(posedge clk) begin
        dff <= a & ~b;
        state <= dff;
    end

    assign q = dff;
endmodule

module TopModule (
    input wire clk,
    input wire resetn,
    input wire [2:0] r,
    output reg [2:0] g
);

// State definitions
localparam [1:0] STATE_A = 2'b00;
localparam [1:0] STATE_B = 2'b01;
localparam [1:0] STATE_C = 2'b10;
localparam [1:0] STATE_D = 2'b11;

// Current state register
reg [1:0] currentState;

// Next state logic
always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
        currentState <= STATE_A;
    end else begin
        case (currentState)
            STATE_A: begin
                if ((r == 3'b000) && (currentState != STATE_D)) begin
                    currentState <= STATE_A;
                end else if (r[0]) begin
                    currentState <= STATE_B;
                end else if ((r[1]) && !(r[0])) begin
                    currentState <= STATE_C;
                end else if ((r == 3'b000) && (currentState == STATE_D)) begin
                    currentState <= STATE_A;
                end else begin
                    currentState <= STATE_D;
                end
            end
            STATE_B: begin
                if (r[0]) begin
                    currentState <= STATE_B;
                end else begin
                    currentState <= STATE_A;
                end
            end
            STATE_C: begin
                if (r[1]) begin
                    currentState <= STATE_C;
                end else begin
                    currentState <= STATE_A;
                end
            end
            default: currentState <= STATE_A; // Default to state A
        endcase
    end
end

// Output logic based on current state
always @(*) begin
    g = 3'b000;
    case (currentState)
        STATE_A: begin
            if ((r[0] || r[1] || r[2])) begin
                if (r[0]) begin
                    g[0] = 1'b1;
                end else if (r[1]) begin
                    g[1] = 1'b1;
                end else if (r[2]) begin
                    g[2] = 1'b1;
                end
            end
        end
        STATE_B: begin
            g[0] = 1'b1;
        end
        STATE_C: begin
            g[1] = 1'b1;
        end
        default: begin
            g = 3'b000;
        end
    endcase
end

endmodule

module TopModule (
  input clk,
  input resetn,
  input [3:1] r,
  output [3:1] g
);

  parameter A=0, B=1, C=2, D=3;
  reg [1:0] state, next;

  always @(posedge clk) begin
    if (~resetn) state <= A;
    else state <= next;
  end

  always@(state,r) begin
    case (state)
      A: if (r[1]) next = B;
         else if (r[2]) next = C;
         else if (r[3]) next = D;
         else next = A;
      B: next = r[1] ? B : A;
      C: next = r[2] ? C : A;
      D: next = r[3] ? D : A;
      default: next = 'x;
    endcase
  end

  assign g[1] = (state == B);
  assign g[2] = (state == C);
  assign g[3] = (state == D);

endmodule

module TopModule (
    input wire d,
    input wire done_counting,
    input wire ack,
    input wire [9:0] state,
    output reg B3_next,
    output reg S_next,
    output reg S1_next,
    output reg Count_next,
    output reg Wait_next,
    output reg done,
    output reg counting,
    output reg shift_ena
);

// State Encoding
parameter S = 10'b0000000001;
parameter S1 = 10'b0000000010;
parameter S11 = 10'b0000000100;
parameter S110 = 10'b0000001000;
parameter B0 = 10'b0000010000;
parameter B1 = 10'b0000100000;
parameter B2 = 10'b0001000000;
parameter B3 = 10'b0010000000;
parameter Count = 10'b0100000000;
parameter Wait = 10'b1000000000;

// Next State Logic
reg [9:0] next_state;

always @(*) begin
    case (state)
        S:
            if (d == 0) next_state = S;
            else next_state = S1;
        S1:
            if (d == 0) next_state = S;
            else next_state = (d == 1) ? S11 : S1;
        S11:
            if (d == 0) next_state = S110;
            else next_state = S11;
        S110:
            if (d == 0) next_state = S;
            else next_state = B0;
        B0: next_state = B1;
        B1: next_state = B2;
        B2: next_state = B3;
        B3: next_state = Count;
        Count:
            if (done_counting == 0) next_state = Count;
            else next_state = Wait;
        Wait:
            if (ack == 0) next_state = Wait;
            else next_state = S;
        default: next_state = S; // Default to state S
    endcase
end

// Output Logic
assign B3_next = (next_state == B3);
assign S_next = (next_state == S);
assign S1_next = (next_state == S1);
assign Count_next = (next_state == Count);
assign Wait_next = (next_state == Wait);
assign done = (next_state == Wait) && ack;
assign counting = (next_state == Count);
assign shift_ena = ((next_state >= B0) && (next_state <= B3));

endmodule

module TopModule (
  input d,
  input done_counting,
  input ack,
  input [9:0] state, // 10-bit one-hot current state
  output B3_next,
  output S_next,
  output S1_next,
  output Count_next,
  output Wait_next,
  output done,
  output counting,
  output shift_ena
);

  parameter S=0, S1=1, S11=2, S110=3, B0=4, B1=5, B2=6, B3=7, Count=8, Wait=9;

  assign B3_next = state[B2];
  assign S_next = state[S]&~d | state[S1]&~d | state[S110]&~d | state[Wait]&ack;
  assign S1_next = state[S]&d;
  assign Count_next = state[B3] | state[Count]&~done_counting;
  assign Wait_next = state[Count]&done_counting | state[Wait]&~ack;

  assign done = state[Wait];
  assign counting = state[Count];
  assign shift_ena = |state[B3:B0];

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  input dig,
  output walk_left,
  output walk_right,
  output aaah,
  output digging
);

  parameter WL=0, WR=1, FALLL=2, FALLR=3, DIGL=4, DIGR=5;
  reg [2:0] state;
  reg [2:0] next;

  always_comb begin
    case (state)
      WL: if (!ground) next = FALLL;
        else if (dig) next = DIGL;
        else if (bump_left) next = WR;
        else next = WL;
      WR:
        if (!ground) next = FALLR;
        else if (dig) next = DIGR;
        else if (bump_right) next = WL;
        else next = WR;
      FALLL: next = ground ? WL : FALLL;
      FALLR: next = ground ? WR : FALLR;
      DIGL: next = ground ? DIGL : FALLL;
      DIGR: next = ground ? DIGR : FALLR;
    endcase
  end

  always @(posedge clk, posedge areset) begin
    if (areset) state <= WL;
      else state <= next;
  end

  assign walk_left = (state==WL);
  assign walk_right = (state==WR);
  assign aaah = (state == FALLL) || (state == FALLR);
  assign digging = (state == DIGL) || (state == DIGR);

endmodule

module TopModule (
    input wire clk,
    input wire areset,
    input wire bump_left,
    input wire bump_right,
    input wire ground,
    input wire dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

// State definition
localparam IDLE = 3'b000;
localparam WALK_LEFT = 3'b001;
localparam WALK_RIGHT = 3'b010;
localparam FALLING = 3'b011;
localparam DIGGING = 3'b100;

reg [2:0] current_state, next_state;

always @(posedge clk or posedge areset) begin
    if (areset) begin
        current_state <= WALK_LEFT;
    end else begin
        current_state <= next_state;
    end
end

always @(*) begin
    // Default assignments
    walk_left = 0;
    walk_right = 0;
    aaah = 0;
    digging = 0;
    next_state = current_state;

    case (current_state)
        IDLE:
            begin
                walk_left = 1;
                next_state = WALK_LEFT;
            end

        WALK_LEFT:
            begin
                if (bump_left || (bump_right && !ground))
                    next_state = WALK_RIGHT;
                else if (!ground)
                    next_state = FALLING;
                else if (dig && ground)
                    next_state = DIGGING;
            end

        WALK_RIGHT:
            begin
                if (bump_right || (bump_left && !ground))
                    next_state = WALK_LEFT;
                else if (!ground)
                    next_state = FALLING;
                else if (dig && ground)
                    next_state = DIGGING;
            end

        FALLING:
            begin
                aaah = 1;
                if (ground)
                    next_state = WALK_LEFT; // Resume walking left after landing
            end

        DIGGING:
            begin
                digging = 1;
                if (!ground)
                    next_state = FALLING;
                else if (!bump_left && !bump_right)
                    next_state = WALK_LEFT; // Continue walking left after digging
            end

        default:
            next_state = IDLE;
    endcase
end

endmodule

module TopModule (
    input wire clk,
    input wire areset,

    input wire predict_valid,
    input wire [6:0] predict_pc,
    output reg predict_taken,
    output reg [6:0] predict_history,

    input wire train_valid,
    input wire train_taken,
    input wire train_mispredicted,
    input wire [6:0] train_history,
    input wire [6:0] train_pc
);

    // Global Branch History Register
    reg [6:0] global_history;

    // Pattern History Table (PHT) with 128 entries of 2-bit saturating counters
    reg [1:0] pht [127:0];

    // Function to calculate the index from PC and Global History
    function [6:0] calc_index;
        input [6:0] pc, history;
        begin
            calc_index = pc ^ history;
        end
    endfunction

    // Always block for handling predictions
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            global_history <= 7'b0;
            predict_taken <= 1'b0;
        end else if (predict_valid) begin
            // Predict branch direction based on PHT
            reg [1:0] pht_state;
            pht_state = pht[calc_index(predict_pc, global_history)];
            predict_taken <= (pht_state == 2'b11);
            predict_history <= global_history;
        end
    end

    // Always block for handling training
    always @(posedge clk or posedge areset) begin
        if (!areset && train_valid) begin
            reg [6:0] index;
            index = calc_index(train_pc, train_history);

            // Saturating Counter Update
            case (pht[index])
                2'b00: pht[index] <= (train_mispredicted) ? 2'b01 : 2'b00;
                2'b01: pht[index] <= (train_mispredicted) ? 2'b10 : 2'b01;
                2'b10: pht[index] <= (train_mispredicted) ? 2'b11 : 2'b10;
                2'b11: pht[index] <= (train_mispredicted) ? 2'b11 : 2'b10; // No change
            endcase

            // Recover global history if mispredicted
            if (train_mispredicted) begin
                global_history <= train_history;
            end else begin
                // Shift global history left and add new bit from train_taken
                global_history <= {global_history[6:1], train_taken};
            end
        end
    end

endmodule

module TopModule (
  input clk,
  input areset,

  input predict_valid,
  input [6:0] predict_pc,
  output predict_taken,
  output [6:0] predict_history,

  input train_valid,
  input train_taken,
  input train_mispredicted,
  input [6:0] train_history,
  input [6:0] train_pc
);

  parameter n = 7;
  logic [1:0] pht [2**n-1:0];

  parameter [1:0] SNT = 0, LNT = 1, LT = 2, ST = 3;

  logic [n-1:0] predict_history_r;
  wire [n-1:0] predict_index = predict_history_r ^ predict_pc;
  wire [n-1:0] train_index = train_history ^ train_pc;

  always@(posedge clk, posedge areset)
    if (areset) begin
      for (integer i=0; i<2**n; i=i+1)
        pht[i] = LNT;
      predict_history_r = 0;
        end  else begin
      if (predict_valid)
        predict_history_r <= {predict_history_r, predict_taken};
      if(train_valid) begin
        if(pht[train_index] < 3 && train_taken)
          pht[train_index] <= pht[train_index] + 1;
        else if(pht[train_index] > 0 && !train_taken)
          pht[train_index] <= pht[train_index] - 1;
        if (train_mispredicted)
          predict_history_r <= {train_history, train_taken};
      end
    end

  assign predict_taken = predict_valid ? pht[predict_index][1] : 1'bx;
  assign predict_history = predict_valid ? predict_history_r : {n{1'bx}};

endmodule

module TopModule (
    input wire clk,
    input wire reset,
    input wire [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    localparam IDLE = 2'b00;
    localparam FIND_FIRST_BYTE = 2'b01;
    localparam RECEIVE_MESSAGE = 2'b10;

    reg [1:0] state;
    reg [7:0] message_buffer [0:2];
    integer idx;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            out_bytes <= 24'b0;
            done <= 0;
            idx <= 0;
        end else begin
            case (state)
                IDLE:
                    begin
                        if (in[3]) begin
                            state <= FIND_FIRST_BYTE;
                            idx <= 0;
                            message_buffer[idx] <= in;
                        end
                    end
                FIND_FIRST_BYTE:
                    begin
                        if (idx == 2) begin
                            state <= RECEIVE_MESSAGE;
                        end else begin
                            if (in[3]) begin
                                idx <= idx + 1;
                                message_buffer[idx] <= in;
                            end
                        end
                    end
                RECEIVE_MESSAGE:
                    begin
                        done <= 1;
                        out_bytes <= {message_buffer[2], message_buffer[1], message_buffer[0]};
                        state <= IDLE;
                    end
                default:
                    state <= IDLE;
            endcase
        end
    end

endmodule

module TopModule (
  input clk,
  input [7:0] in,
  input reset,
  output [23:0] out_bytes,
  output done
);

  parameter BYTE1=0, BYTE2=1, BYTE3=2, DONE=3;
  reg [1:0] state;
  reg [1:0] next;

  wire in3 = in[3];

  always_comb begin
    case (state)
      BYTE1: next = in3 ? BYTE2 : BYTE1;
      BYTE2: next = BYTE3;
      BYTE3: next = DONE;
      DONE: next = in3 ? BYTE2 : BYTE1;
    endcase
  end

  always @(posedge clk) begin
    if (reset) state <= BYTE1;
      else state <= next;
  end

  assign done = (state==DONE);

  reg [23:0] out_bytes_r;
  always @(posedge clk)
    out_bytes_r <= {out_bytes_r[15:0], in};

  // Implementations may vary: Allow user to do anything while the output
  // doesn't have to be valid.

  assign out_bytes = done ? out_bytes_r : 'x;

endmodule

module TopModule (
    input wire clk,
    input wire areset,
    input wire bump_left,
    input wire bump_right,
    input wire ground,
    input wire dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);
    localparam IDLE = 3'b000;
    localparam WALK_LEFT = 3'b001;
    localparam WALK_RIGHT = 3'b010;
    localparam FALLING = 3'b011;
    localparam DIGGING = 3'b100;

    reg [2:0] state, next_state;
    reg [4:0] fall_counter;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= WALK_LEFT;
            walk_left <= 1;
            walk_right <= 0;
            aaah <= 0;
            digging <= 0;
            fall_counter <= 0;
        end else begin
            state <= next_state;
            case (state)
                IDLE:
                    begin
                        walk_left <= (bump_right && !walk_right) || (!bump_left && walk_right);
                        walk_right <= (bump_left && !walk_left) || (!bump_right && walk_left);
                        aaah <= ground ? 0 : 1;
                        digging <= 0;
                    end
                WALK_LEFT:
                    begin
                        walk_left <= 1;
                        walk_right <= 0;
                        aaah <= ground ? 0 : 1;
                        digging <= ground & dig ? 1 : 0;
                    end
                WALK_RIGHT:
                    begin
                        walk_left <= 0;
                        walk_right <= 1;
                        aaah <= ground ? 0 : 1;
                        digging <= ground & dig ? 1 : 0;
                    end
                FALLING:
                    begin
                        walk_left <= 0;
                        walk_right <= 0;
                        aaah <= 1;
                        digging <= 0;
                        fall_counter <= fall_counter + 1;
                        if (ground) begin
                            if (fall_counter > 20) begin
                                state <= IDLE;
                                aaah <= 0;
                            end else begin
                                state <= WALK_LEFT | WALK_RIGHT;
                                fall_counter <= 0;
                            end
                        end
                    end
                DIGGING:
                    begin
                        walk_left <= 0;
                        walk_right <= 0;
                        aaah <= 0;
                        digging <= 1;
                        if (!ground) begin
                            state <= FALLING;
                            fall_counter <= 1;
                        end
                    end
                default:
                    state <= IDLE;
            endcase
        end
    end

    always @(*) begin
        case ({dig, ground})
            2'b01: next_state = DIGGING;
            2'b10: next_state = FALLING;
            default: next_state = state;
        endcase
    end

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  input dig,
  output walk_left,
  output walk_right,
  output aaah,
  output digging
);

  parameter WL=0, WR=1, FALLL=2, FALLR=3, DIGL=4, DIGR=5, DEAD=6;
  reg [2:0] state;
  reg [2:0] next;

  reg [4:0] fall_counter;

  always_comb begin
    case (state)
      WL: if (!ground) next = FALLL;
        else if (dig) next = DIGL;
        else if (bump_left) next = WR;
        else next = WL;
      WR:
        if (!ground) next = FALLR;
        else if (dig) next = DIGR;
        else if (bump_right) next = WL;
        else next = WR;
      FALLL: next = ground ? (fall_counter >= 20 ? DEAD : WL) : FALLL;
      FALLR: next = ground ? (fall_counter >= 20 ? DEAD : WR) : FALLR;
      DIGL: next = ground ? DIGL : FALLL;
      DIGR: next = ground ? DIGR : FALLR;
      DEAD: next = DEAD;
    endcase
  end

  always @(posedge clk, posedge areset) begin
    if (areset) state <= WL;
      else state <= next;
  end

  always @(posedge clk) begin
    if (state == FALLL || state == FALLR) begin
      if (fall_counter < 20)
        fall_counter <= fall_counter + 1'b1;
    end
    else
      fall_counter <= 0;
  end

  assign walk_left = (state==WL);
  assign walk_right = (state==WR);
  assign aaah = (state == FALLL) || (state == FALLR);
  assign digging = (state == DIGL) || (state == DIGR);

endmodule
